<!DOCTYPE html><html lang="id"><head><meta charset="utf-8"><title>Daftar Kunjungan</title><style>body{font-family:DejaVu Sans,sans-serif;font-size:10px;color:#243f40}h1{font-size:20px}table{width:100%;border-collapse:collapse}th,td{padding:8px;border-bottom:1px solid #dce5e5;text-align:left}th{background:#edf5f3}thead{display:table-header-group}tr{page-break-inside:avoid}</style></head><body><h1>{{ config('app.name') }} · Daftar Kunjungan Gigi</h1><p>Tanggal: {{ $date ?: 'Seluruh tanggal' }} | Status: {{ $status === 'Menunggu' ? 'Terdaftar' : ($status ?: 'Semua') }} | Pencarian: {{ $search ?: '-' }}</p><table><thead><tr><th>No.</th><th>Tanggal</th><th>Pasien / RM</th><th>Dokter</th><th>Keluhan</th><th>Status</th><th>Pembayaran</th></tr></thead><tbody>@forelse($visits as $visit)<tr><td>KJ-{{ $visit->id }}</td><td>{{ $visit->tanggal_kunjungan->format('d/m/Y') }}</td><td>{{ $visit->patient?->nama }}<br>{{ $visit->patient?->no_rm }}</td><td>{{ $visit->doctor?->nama ?? 'Belum ditentukan' }}</td><td>{{ $visit->keluhan ?: '-' }}</td><td>{{ $visit->status === 'Menunggu' ? 'Terdaftar' : $visit->status }}</td><td>{{ $visit->status_pembayaran }}</td></tr>@empty<tr><td colspan="7">Tidak ada kunjungan sesuai filter.</td></tr>@endforelse</tbody></table><p>Total: {{ $visits->count() }} kunjungan.</p></body></html>
